svg.script:
(function () {
  var data = {
    cd: ['DR Kongo', 458, 546], ao: ['Angola', 448, 561], mz: ['Mosambik', 508, 584], mw: ['Malawi', 493, 573],
    ug: ['Uganda', 486, 532], tg: ['Togo', 409, 516], cm: ['Kamerun', 436, 519], na: ['Namibia', 441, 591],
    tz: ['Tansania', 493, 560], rw: ['Ruanda', 480, 535], bi: ['Burundi', 480, 540]
  };
  var popup = document.getElementById('country-popup');
  var label = document.getElementById('country-popup-label');
  var targets = Object.keys(data).map(function (id) { return document.getElementById(id); }).filter(Boolean);
  function showCountry(country) {
    targets.forEach(function (item) { item.classList.remove('is-active'); });
    var entry = data[country.id];
    country.classList.add('is-active');
    label.textContent = entry[0];
    popup.setAttribute('transform', 'translate(' + entry[1] + ' ' + entry[2] + ')');
    popup.style.display = 'block';
  }
  targets.forEach(function (country) {
    var entry = data[country.id];
    country.setAttribute('role', 'button');
    country.setAttribute('tabindex', '0');
    country.setAttribute('aria-label', entry[0] + ' anzeigen');
    country.addEventListener('click', function (event) { event.stopPropagation(); showCountry(country); });
    country.addEventListener('keydown', function (event) { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); showCountry(country); } });
  });
  document.documentElement.addEventListener('click', function (event) { if (!event.target.closest || !event.target.closest('[role="button"]')) { popup.style.display = 'none'; targets.forEach(function (item) { item.classList.remove('is-active'); }); } });
}());
